/**
 * utils/printPalette.js. The print palette, for every document this business sends a client or
 * the IRS: the invoice, the P&L and balance-sheet builders, Form 1065, the K-1s and the
 * 1099-NECs.
 *
 * One home, because a per-document copy drifts by name as well as by value: the same hex was
 * called `light` in two files and `lightRule` in two others, which is a rule with two names
 * rather than two rules.
 *
 * It lives in `utils/` and NOT beside the documents in `components/shared/pdf/` because
 * `utils/ledgerPdf.js` needs it too, and a `utils` to `components` import is the one layer
 * inversion this repo licenses and should not gain a second.
 *
 * @gotcha Print, not screen. These are dark-on-warm-white for paper and a PDF viewer; the app's
 *         own palette is the dark theme in `App.css` and the two must not be crossed.
 * @see docs/DESIGN.md
 */

/** Common to every printed document. */
export const PRINT = {
  nearBlack:  '#1A1A1A',
  orange:     '#E8743B',
  warmWhite:  '#FAF6F0',
  /** Body text that steps back. Four of the five documents use it. */
  muted:      '#555555',
  /**
   * A lighter grey still, for labels on the invoice and the ledger reports. Tuned for PAPER:
   * 4.94:1 on the warm-white plate and 4.64:1 on the alternating row, which is the tighter of
   * the two, at the 7.5pt to 8.5pt these labels are actually set in.
   */
  mutedGray:  '#6E6B64',
  /**
   * The same job on the invoice's dark header and footer BANDS, where the paper grey drops to
   * 3.47:1 and this one is 4.81:1. Two surfaces, two greys; one grey cannot serve both.
   */
  mutedOnDark: '#8A8680',
  /** Hairline rules and table borders. Was `light` in two files, `lightRule` in two. */
  lightRule:  '#E5DFD6',
  /** The heavier rule the three tax forms use for box edges. */
  rule:       '#888888',
  /**
   * The invoice header divider, which sits on the dark banner rather than on paper and so
   * cannot use `lightRule`. It was hard-coded in InvoicePDF against this module's own
   * one-home rule, and it was the last print colour with no name.
   */
  darkRule:   '#3A3A3A',
};
