/**
 * utils/ledgerPdf.js - lazy-loaded ledger PDF builders + downloaders
 * (P&L, Balance Sheet, Trial Balance).
 *
 * Consumes the pure report structures from utils/ledger.js and renders them to
 * PDF. Callers in LedgerPage dynamic-import this at click time:
 *   const m = await import('../../utils/ledgerPdf'); await m.downloadPLPdf(...)
 *
 * @perf imported ONLY via dynamic import() so @react-pdf/renderer stays out of
 *       the eager admin chunk. Never add a static import of this file; that
 *       would drag react-pdf back into the main bundle (the reason ledger.js
 *       was split into pure-math vs this).
 */
import React from 'react';
import { Document, Page, Text, View, StyleSheet, pdf } from '@react-pdf/renderer';
import { fmtMoney, fmtDate } from './format';
import { downloadBlob } from './download';
import { PRINT } from './printPalette';

// Brand palette (mirrors InvoicePreviewModal)
// Its own two: a signed figure on a P&L is red or green, which no other
// document has a use for.
const P = { ...PRINT, red: '#C73E3E', green: '#1C7A3A' };

const pdfStyles = StyleSheet.create({
  page:    { padding: 36, fontFamily: 'Helvetica', fontSize: 10, color: P.nearBlack, backgroundColor: P.warmWhite },
  brand:   { fontSize: 16, color: P.orange, marginBottom: 4, letterSpacing: 2 },
  title:   { fontSize: 18, marginBottom: 2 },
  meta:    { fontSize: 9, color: P.mutedGray, marginBottom: 16 },
  section: { marginTop: 12, fontSize: 11, color: P.orange, textTransform: 'uppercase', letterSpacing: 1, paddingBottom: 3, borderBottomWidth: 0.5, borderBottomColor: P.lightRule, borderBottomStyle: 'solid' },
  row:     { flexDirection: 'row', paddingVertical: 3 },
  cellName:{ flex: 1 },
  cellNum: { width: 110, textAlign: 'right' },
  cellNum2:{ width: 90,  textAlign: 'right' },
  total:   { flexDirection: 'row', paddingVertical: 6, borderTopWidth: 0.5, borderTopColor: P.lightRule, borderTopStyle: 'solid', fontWeight: 700 },
  net:     { marginTop: 16, fontSize: 16, textAlign: 'right' },
  banner:  { marginTop: 20, fontSize: 13, textAlign: 'center', padding: 8 },
});

/** Shared report header: wordmark, title, and a period/as-of label. */
function brandHeader(title, periodLabel, brand) {
  return (
    <View>
      <Text style={pdfStyles.brand}>{(brand && brand.legal_name) || 'NYSTERYS MEDIA LLC'}</Text>
      <Text style={pdfStyles.title}>{title}</Text>
      <Text style={pdfStyles.meta}>{periodLabel || ''}</Text>
    </View>
  );
}

/** Render a P&L report object (from buildPLReport) to a react-pdf Document. */
export function buildPLPdfDoc(pl, periodLabel, brand) {
  const renderRows = (rows) => rows.map((r) => (
    <View key={r.account.id} style={pdfStyles.row}>
      <Text style={pdfStyles.cellName}>{r.account.code}  {r.account.name}</Text>
      <Text style={pdfStyles.cellNum}>{fmtMoney(r.balance)}</Text>
    </View>
  ));
  return (
    <Document>
      <Page size="LETTER" style={pdfStyles.page}>
        {brandHeader('Profit & Loss', periodLabel, brand)}

        <Text style={pdfStyles.section}>Revenue</Text>
        {renderRows(pl.revenue)}
        <View style={pdfStyles.total}>
          <Text style={pdfStyles.cellName}>Total Revenue</Text>
          <Text style={pdfStyles.cellNum}>{fmtMoney(pl.totalRevenue)}</Text>
        </View>

        <Text style={pdfStyles.section}>Cost of Revenue</Text>
        {renderRows(pl.costOfRevenue)}
        <View style={pdfStyles.total}>
          <Text style={pdfStyles.cellName}>Total Cost of Revenue</Text>
          <Text style={pdfStyles.cellNum}>{fmtMoney(pl.totalCostOfRevenue)}</Text>
        </View>

        <View style={pdfStyles.total}>
          <Text style={pdfStyles.cellName}>Gross Profit</Text>
          <Text style={pdfStyles.cellNum}>{fmtMoney(pl.grossProfit)}</Text>
        </View>

        <Text style={pdfStyles.section}>Operating Expenses</Text>
        {renderRows(pl.operatingExpenses)}
        <View style={pdfStyles.total}>
          <Text style={pdfStyles.cellName}>Total Operating Expenses</Text>
          <Text style={pdfStyles.cellNum}>{fmtMoney(pl.totalOperatingExpenses)}</Text>
        </View>

        <Text style={[pdfStyles.net, { color: pl.netIncome >= 0 ? P.orange : P.red }]}>
          NET INCOME  {fmtMoney(pl.netIncome)}
        </Text>
      </Page>
    </Document>
  );
}

/** Render a Balance Sheet object (from buildBalanceSheet) to a react-pdf Document. */
export function buildBalanceSheetPdfDoc(bs, asOfDate, brand) {
  const renderRows = (rows) => rows.map((r) => (
    <View key={r.account.id} style={pdfStyles.row}>
      <Text style={pdfStyles.cellName}>{r.account.code}  {r.account.name}</Text>
      <Text style={pdfStyles.cellNum}>{fmtMoney(r.balance)}</Text>
    </View>
  ));
  return (
    <Document>
      <Page size="LETTER" style={pdfStyles.page}>
        {brandHeader('Balance Sheet', `As of ${fmtDate(asOfDate)}`, brand)}

        <Text style={pdfStyles.section}>Assets</Text>
        {renderRows(bs.assets)}
        <View style={pdfStyles.total}>
          <Text style={pdfStyles.cellName}>Total Assets</Text>
          <Text style={pdfStyles.cellNum}>{fmtMoney(bs.totalAssets)}</Text>
        </View>

        <Text style={pdfStyles.section}>Liabilities</Text>
        {renderRows(bs.liabilities)}
        <View style={pdfStyles.total}>
          <Text style={pdfStyles.cellName}>Total Liabilities</Text>
          <Text style={pdfStyles.cellNum}>{fmtMoney(bs.totalLiabilities)}</Text>
        </View>

        <Text style={pdfStyles.section}>Equity</Text>
        {renderRows(bs.equity)}
        <View style={pdfStyles.total}>
          <Text style={pdfStyles.cellName}>Total Equity</Text>
          <Text style={pdfStyles.cellNum}>{fmtMoney(bs.totalEquity)}</Text>
        </View>

        <Text style={[pdfStyles.banner, { color: bs.isBalanced ? P.green : P.red }]}>
          {bs.isBalanced ? 'BALANCED  ✓' : 'OUT OF BALANCE'}
        </Text>
      </Page>
    </Document>
  );
}

/** Render a Trial Balance object (from buildTrialBalance) to a react-pdf Document. */
export function buildTrialBalancePdfDoc(tb, asOfDate, brand) {
  const TYPE_LABEL = { asset: 'Assets', liability: 'Liabilities', equity: 'Equity', revenue: 'Revenue', expense: 'Expenses' };
  return (
    <Document>
      <Page size="LETTER" style={pdfStyles.page}>
        {brandHeader('Trial Balance', `As of ${fmtDate(asOfDate)}`, brand)}

        <View style={pdfStyles.row}>
          <Text style={pdfStyles.cellName}>Account</Text>
          <Text style={pdfStyles.cellNum2}>Debit</Text>
          <Text style={pdfStyles.cellNum2}>Credit</Text>
        </View>

        {tb.groups.map((g) => (
          <View key={g.type} wrap={false}>
            <Text style={pdfStyles.section}>{TYPE_LABEL[g.type] || g.type}</Text>
            {g.rows.map((r) => (
              <View key={r.account.id} style={pdfStyles.row}>
                <Text style={pdfStyles.cellName}>{r.account.code}  {r.account.name}{r.isAbnormal ? '  (abnormal)' : ''}</Text>
                <Text style={pdfStyles.cellNum2}>{r.debit ? fmtMoney(r.debit) : ''}</Text>
                <Text style={pdfStyles.cellNum2}>{r.credit ? fmtMoney(r.credit) : ''}</Text>
              </View>
            ))}
          </View>
        ))}

        <View style={pdfStyles.total}>
          <Text style={pdfStyles.cellName}>TOTALS</Text>
          <Text style={pdfStyles.cellNum2}>{fmtMoney(tb.totalDebit)}</Text>
          <Text style={pdfStyles.cellNum2}>{fmtMoney(tb.totalCredit)}</Text>
        </View>

        <Text style={[pdfStyles.banner, { color: tb.isBalanced ? P.green : P.red }]}>
          {tb.isBalanced ? 'BALANCED  ✓' : `OUT OF BALANCE  ${fmtMoney(Math.abs(tb.imbalance))}`}
        </Text>
      </Page>
    </Document>
  );
}

/** Save a Blob to disk via a transient object URL (revoked after the click). */

/** Build + download the P&L PDF. */
export async function downloadPLPdf(pl, periodLabel, brand, fileName) {
  const blob = await pdf(buildPLPdfDoc(pl, periodLabel, brand)).toBlob();
  downloadBlob(blob, fileName);
}

/** Build + download the Balance Sheet PDF. */
export async function downloadBalanceSheetPdf(bs, asOfDate, brand, fileName) {
  const blob = await pdf(buildBalanceSheetPdfDoc(bs, asOfDate, brand)).toBlob();
  downloadBlob(blob, fileName);
}

/** Build + download the Trial Balance PDF. */
export async function downloadTrialBalancePdf(tb, asOfDate, brand, fileName) {
  const blob = await pdf(buildTrialBalancePdfDoc(tb, asOfDate, brand)).toBlob();
  downloadBlob(blob, fileName);
}
